import {demoState,validateState,evaluate,summaries,latestReview,recordReview,addCase,fingerprint,TYPES} from './engine.mjs';
const $=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='tracework-workspace-v2';let state=demoState(),selected=state.cases[0].id,storage=true,started=false,currentPage='overview';let notice='';
try{const raw=localStorage.getItem(KEY);if(raw)state=validateState(JSON.parse(raw));}catch{notice='Saved workspace could not be loaded. The demo is available; import a valid backup to recover your work.';}
function notify(message){$('toast').textContent=message;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storage=true;}catch{storage=false;notify('Browser storage unavailable or full. Export your workspace before closing this page.');}}
function download(name,value,type='application/json'){const blob=new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type});const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function visibleCases(){const query=$('search').value.toLowerCase();const filter=$('filter').value;return state.cases.filter(c=>{const a=evaluate(c,'baseline').pass,b=evaluate(c,'candidate').pass;return (!query||`${c.id} ${c.title} ${c.category}`.toLowerCase().includes(query))&&(filter==='all'||filter==='regression'&&a&&!b||filter==='pending'&&!latestReview(state,c)||filter==='resolved'&&!!latestReview(state,c)||filter==='failed'&&!b);});}
function showPage(page,updateHash=true){if(!['overview','workbench','study','evidence'].includes(page))page='overview';currentPage=page;for(const p of ['overview','workbench','study','evidence'])$(p).classList.toggle('hide',p!==page);document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);if(b.dataset.page===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(page==='workbench')render();if(updateHash)history.replaceState(null,'',`#${page}`);window.scrollTo(0,0);}
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.page)));$('reviewShortcut').onclick=()=>{$('filter').value='pending';showPage('workbench');};window.addEventListener('hashchange',()=>showPage(location.hash.slice(1),false));
function classify(c){const a=evaluate(c,'baseline').pass,b=evaluate(c,'candidate').pass;return a&&!b?'Regression':!a&&b?'Improvement':b?'Stable pass':'Stable fail';}
function pill(s){return `<span class="pill ${s==='Regression'||s==='Fail'||s==='reject'?'bad':s==='Pass'||s==='Improvement'||s==='approve'?'good':'neutral'}">${esc(s)}</span>`;}
function ruleLabel(rule){const label={require_text:'Output contains',forbid_text:'Output excludes',require_event:'Trace includes',forbid_event:'Trace excludes',max_latency:'Latency ≤',max_cost:'Cost ≤'}[rule.type];return `${label} ${rule.type==='max_cost'?'$':''}${rule.value}${rule.type==='max_latency'?' ms':''}`;}
function traceCard(c,key){const r=c[key],result=evaluate(c,key);return `<article class="trace-card"><div class="bar"><h3>${key==='baseline'?'Baseline A':'Candidate B'}</h3>${pill(result.pass?'Pass':'Fail')}</div><p class="runmeta">${r.latencyMs.toLocaleString()} ms · $${r.costUsd.toFixed(4)} · fixture values</p><ol class="events">${r.events.length?r.events.map(e=>`<li><code>${esc(e)}</code></li>`).join(''):'<li>No tool events</li>'}</ol><span class="eyebrow">Final output</span><p class="output">${esc(r.output)}</p><details><summary>Inspect run JSON</summary><pre>${esc(JSON.stringify(r,null,2))}</pre></details></article>`;}
function render(){const summary=summaries(state.cases),visible=visibleCases();if(!visible.some(c=>c.id===selected))selected=visible[0]?.id;const pending=state.cases.filter(c=>!latestReview(state,c)).length;$('metric-pass').textContent=`${summary.candidate} / ${summary.total}`;$('metric-regress').textContent=summary.regressions;$('metric-review').textContent=pending;$('suiteCount').textContent=`${visible.length} of ${summary.total} cases`;$('workspace-state').textContent=storage?'Saved on this device':'Memory only · export to save';$('release').innerHTML=summary.total===0?'<b>No tests in this suite.</b> Create a case to begin.':`<b>${summary.regressions?'Hold candidate':'No rubric regressions detected'}</b><span>${summary.regressions} regression${summary.regressions===1?'':'s'} · ${pending} unreviewed case${pending===1?'':'s'} · rule-based fixture checks only</span>`;$('case-list').innerHTML=visible.map(c=>`<button class="case-item ${c.id===selected?'selected':''}" data-id="${esc(c.id)}" aria-pressed="${c.id===selected}"><span class="case-meta">${esc(c.id)} · ${esc(c.category)}</span><strong>${esc(c.title)}</strong><span class="case-bottom">${pill(classify(c))}<span>${latestReview(state,c)?'Reviewed':'Needs review'}</span></span></button>`).join('')||'<div class="empty"><b>No matching cases</b><p>Change the search or filter, or create a new test.</p><button id="clearFilters">Clear filters</button></div>';$('clearFilters')?.addEventListener('click',()=>{$('search').value='';$('filter').value='all';render();});document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{selected=b.dataset.id;render();});const c=state.cases.find(c=>c.id===selected);if(!c){$('case-detail').innerHTML='<div class="empty"><h3>Nothing to review</h3><p>Create a test or choose another filter.</p></div>';renderLog();return;}
const baseline=evaluate(c,'baseline'),candidate=evaluate(c,'candidate'),review=latestReview(state,c);$('case-detail').innerHTML=`<div class="detail-heading"><div><span class="eyebrow">${esc(c.id)} / ${esc(c.category)}</span><h2>${esc(c.title)}</h2></div>${pill(classify(c))}</div><p class="task"><b>Task</b> ${esc(c.task)}</p><div class="tablewrap rubric"><table><caption>Executable rubric · exact event checks and case-insensitive text matching</caption><thead><tr><th scope="col">Criterion</th><th scope="col">Baseline</th><th scope="col">Candidate</th></tr></thead><tbody>${candidate.checks.map((x,i)=>`<tr><td>${esc(ruleLabel(x.rule))}</td><td>${pill(baseline.checks[i].pass?'Pass':'Fail')}</td><td>${pill(x.pass?'Pass':'Fail')}</td></tr>`).join('')}</tbody></table></div><div class="trace-grid">${traceCard(c,'baseline')}${traceCard(c,'candidate')}</div><form id="review-form" class="review-panel"><div><span class="eyebrow">Human adjudication</span><h3>${review?'Revise the decision':'What should happen next?'}</h3><p>Automated checks show symptoms. Your rationale records the judgment.</p>${review?`<p class="small">Current decision: <b>${esc(review.disposition)}</b> · ${esc(review.rationale)}</p>`:''}</div><label for="disposition">Decision</label><select id="disposition"><option value="reject">Reject candidate</option><option value="rerun">Request another run</option><option value="approve">Approve candidate</option></select><label for="rationale">Evidence and rationale <span class="small">Required · max 2,000 characters</span></label><textarea id="rationale" required maxlength="2000" placeholder="Name the trace event and rubric criterion supporting your decision."></textarea><div class="bar"><span class="small">Recorded locally. Actor identity is not authenticated.</span><button class="primary" type="submit">${review?'Record revised decision':'Record decision'}</button></div></form>`;
$('review-form').onsubmit=e=>{e.preventDefault();try{const rationale=$('rationale').value;state=recordReview(state,c.id,$('disposition').value,rationale);persist();render();notify(`Decision recorded for ${c.id}.${storage?'':' Export to preserve it.'}`);}catch(error){$('rationale').setCustomValidity(error.message);$('rationale').reportValidity();$('rationale').oninput=()=>$('rationale').setCustomValidity('');notify(error.message);}};renderLog();}
function renderLog(){const rows=state.reviews.slice().reverse();$('decision-count').textContent=rows.length;$('review-log').innerHTML=rows.length?`<table><thead><tr><th scope="col">Case</th><th scope="col">Decision</th><th scope="col">Evidence</th><th scope="col">Recorded</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.caseId)}</td><td>${pill(r.disposition)}</td><td>${esc(r.rationale)}</td><td><time datetime="${esc(r.timestamp)}">${esc(new Date(r.timestamp).toLocaleString())}</time></td></tr>`).join('')}</tbody></table>`:'<p class="small">No decisions yet. Review a case to create the first event.</p>';}
$('search').oninput=render;$('filter').onchange=render;
$('run-suite').onclick=()=>{started=true;render();const s=summaries(state.cases);notify(`Evaluation complete: ${s.candidate}/${s.total} candidate passes; ${s.regressions} regressions. Deterministic checks over supplied fixtures; no model call.`);$('run-suite').textContent='Run checks again';};
$('export-workspace').onclick=()=>{download('tracework-workspace.json',{...state,exportedAt:new Date().toISOString(),synthetic:true});notify('Workspace exported. This file includes your case text and review notes.');};
$('export-results').onclick=()=>{download('tracework-results.json',{schemaVersion:2,synthetic:true,evaluatedAt:new Date().toISOString(),summary:summaries(state.cases),results:state.cases.map(c=>({caseId:c.id,baseline:evaluate(c,'baseline'),candidate:evaluate(c,'candidate'),review:latestReview(state,c)||null}))});notify('Rule evaluation results exported.');};
$('import-workspace').onclick=()=>$('import-file').click();$('import-file').onchange=async e=>{const input=e.target,file=input.files[0];if(!file)return;try{if(file.size>2_000_000)throw Error('Workspace files must be smaller than 2 MB.');const next=validateState(JSON.parse(await file.text()));if(!confirm(`Replace this device's workspace with ${next.cases.length} cases and ${next.reviews.length} reviews? Export your current workspace first if needed.`))return;state=next;selected=state.cases[0]?.id;$('search').value='';$('filter').value='all';persist();render();notify('Workspace imported and validated.');}catch(error){notify(`Import rejected. ${error.message} Your current workspace was kept.`);}finally{input.value='';}};
$('reset-demo').onclick=()=>{if(!confirm('Replace all local cases and decisions with the demo? Export your work first.'))return;state=demoState();selected=state.cases[0].id;started=false;$('search').value='';$('filter').value='all';persist();render();notify('Demo restored.');};
const modal=$('case-modal');$('new-case').onclick=()=>{$('case-error').textContent='';if(typeof modal.showModal==='function')modal.showModal();else modal.setAttribute('open','');$('new-id').focus();};$('close-modal').onclick=()=>modal.close();
$('case-form').onsubmit=e=>{e.preventDefault();try{const type=$('new-rule').value,numeric=type.startsWith('max_'),raw=$('new-value').value;const events=id=>$(id).value.split(',').map(x=>x.trim()).filter(Boolean);const run=prefix=>({output:$(prefix+'-output').value,events:events(prefix+'-events'),latencyMs:Number($(prefix+'-latency').value),costUsd:Number($(prefix+'-cost').value)});state=addCase(state,{id:$('new-id').value,title:$('new-title').value,task:$('new-task').value,category:'Custom',baseline:run('base'),candidate:run('cand'),rules:[{type,value:numeric?Number(raw):raw}]});selected=state.cases.at(-1).id;$('filter').value='all';$('search').value='';persist();render();modal.close();$('case-form').reset();$('new-value').type='text';$('case-error').textContent='';notify(`Case ${selected} created and evaluated.`);$('new-case').focus();}catch(error){$('case-error').textContent=error.message;}};
$('new-rule').onchange=()=>{$('new-value').type=$('new-rule').value.startsWith('max_')?'number':'text';$('new-value').step='any';$('new-value').min='0';};$('download-example').onclick=()=>download('tracework-example-workspace.json',demoState());
showPage(location.hash.slice(1)||'overview',false);if(notice)notify(notice);
